    "updatedAt" timestamp(3) without time zone NOT NULL,
    "deletedAt" timestamp(3) without time zone,
    CONSTRAINT admission_exit_after_entry_check CHECK ((("exitDate" IS NULL) OR ("exitDate" >= "admissionDate"))),
    CONSTRAINT admission_exit_check CHECK (((status <> ALL (ARRAY['COMPLETED'::public."AdmissionStatus", 'CANCELLED'::public."AdmissionStatus", 'TRANSFERRED_OUT'::public."AdmissionStatus"])) OR (("exitDate" IS NOT NULL) AND ("exitReason" IS NOT NULL)))),
    CONSTRAINT admission_no_blank_check CHECK ((length(TRIM(BOTH FROM "admissionNo")) > 0)),
    CONSTRAINT admission_no_self_chain_check CHECK ((("previousAdmissionId" IS NULL) OR ("previousAdmissionId" <> id))),
    CONSTRAINT admission_open_has_no_exit_check CHECK (((status = ANY (ARRAY['COMPLETED'::public."AdmissionStatus", 'CANCELLED'::public."AdmissionStatus", 'TRANSFERRED_OUT'::public."AdmissionStatus"])) OR (("exitDate" IS NULL) AND ("exitReason" IS NULL))))
);


