    "sourceApplicantId" text,
    "createdBy" text,
    "updatedBy" text,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL,
    "deletedAt" timestamp(3) without time zone,
    CONSTRAINT student_code_nonblank_check CHECK ((length(TRIM(BOTH FROM "studentCode")) > 0)),
    CONSTRAINT student_display_name_nonblank_check CHECK ((length(TRIM(BOTH FROM "displayName")) > 0)),
    CONSTRAINT student_dob_plausible_check CHECK (((dob > '1900-01-01 00:00:00'::timestamp without time zone) AND (dob <= CURRENT_DATE))),
    CONSTRAINT student_origin_check CHECK ((("createdVia" = 'MIGRATION'::public."StudentCreationMode") OR ("sourceApplicantId" IS NOT NULL)))
);


