--
-- Name: admission_one_active; Type: INDEX; Schema: public; Owner: postgres
--

CREATE UNIQUE INDEX admission_one_active ON public."Admission" USING btree ("studentId") WHERE ((status = 'ACTIVE'::public."AdmissionStatus") AND ("deletedAt" IS NULL));


--
-- Name: applicant_one_active; Type: INDEX; Schema: public; Owner: postgres
--

CREATE UNIQUE INDEX applicant_one_active ON public."Applicant" USING btree ("personId", "branchId", "academicYearId") WHERE (("personId" IS NOT NULL) AND ("deletedAt" IS NULL) AND ("admissionStatus" <> ALL (ARRAY['REJECTED'::public."AdmissionApplicationStatus", 'WITHDRAWN'::public."AdmissionApplicationStatus", 'CANCELLED'::public."AdmissionApplicationStatus", 'DEFERRED'::public."AdmissionApplicationStatus"])));


--
-- Name: enrollment_one_primary_per_year; Type: INDEX; Schema: public; Owner: postgres
--

CREATE UNIQUE INDEX enrollment_one_primary_per_year ON public."Enrollment" USING btree ("admissionId", "academicYearId") WHERE (("enrollmentKind" = 'PRIMARY'::public."EnrollmentKind") AND ("deletedAt" IS NULL) AND ("enrollmentStatus" <> ALL (ARRAY['SUPERSEDED'::public."EnrollmentStatus", 'CANCELLED'::public."EnrollmentStatus"])));


--
-- Name: enrollment_rollno_unique; Type: INDEX; Schema: public; Owner: postgres
--

CREATE UNIQUE INDEX enrollment_rollno_unique ON public."Enrollment" USING btree ("academicUnitId", "academicYearId", "rollNumber") WHERE (("rollNumber" IS NOT NULL) AND ("deletedAt" IS NULL) AND ("enrollmentStatus" <> ALL (ARRAY['SUPERSEDED'::public."EnrollmentStatus", 'CANCELLED'::public."EnrollmentStatus"])));


